albums = FileAttachment("top_1000_albums.csv").csv({ typed: true })

// Add decade attribute to each album
albumsWithDecade = albums.map(d =&gt; ({
  ...d,
  decade: `${Math.floor(d.year / 10) * 10}s`
}))

// Decade selection buttons
viewof selectedDecade = Inputs.radio(
  ["1950s", "1960s", "1970s", "1980s", "1990s", "2000s", "2010s", "2020s"],
  { label: "Decade", value: "1970s" }
)

// Search within decade
viewof decadeSearch = Inputs.search(
  albumsWithDecade.filter(d =&gt; d.decade === selectedDecade),
  { placeholder: "Filter albums in this decade..." }
)






























md`### Era Ratings Distribution: **${selectedDecade}** (${decadeSearch.length} albums)`







// Plot ratings distribution for selected decade
Plot.plot({
  width: width,
  height: 240,
  style: {
    background: "#121620",
    color: "#cbd5e1",
    borderRadius: "12px",
    padding: "1rem",
    border: "1px solid rgba(255, 255, 255, 0.08)"
  },
  x: { label: "Release Year" },
  y: { label: "Rating" },
  marks: [
    Plot.dot(decadeSearch, {
      x: "year",
      y: "rating",
      fill: "#00f2fe",
      r: 5,
      fillOpacity: 0.7,
      title: d =&gt; `#${d.rank}: ${d.album} by ${d.artist} (${d.year})\nRating: ⭐ ${d.rating}`
    }),
    Plot.lineY(decadeSearch, Plot.binX({ y: "mean" }, { x: "year", y: "rating", stroke: "#ffd166", strokeWidth: 2 }))
  ]
})







// Gallery of album covers for the decade
html`&lt;div class="album-grid"&gt;
  ${decadeSearch.map(d =&gt; html`
    &lt;div class="album-card"&gt;
      &lt;div class="album-cover-wrap"&gt;
        &lt;img class="album-cover-img" src="${d.image_url}" alt="${d.album}" loading="lazy" /&gt;
        &lt;span class="album-badge"&gt;#${d.rank}&lt;/span&gt;
      &lt;/div&gt;
      &lt;div class="album-info"&gt;
        &lt;div class="album-title" title="${d.album}"&gt;${d.album}&lt;/div&gt;
        &lt;div class="album-artist" title="${d.artist}"&gt;${d.artist} (${d.year})&lt;/div&gt;
        &lt;div class="album-meta"&gt;
          &lt;span&gt;⭐ ${d.rating.toFixed(2)}&lt;/span&gt;
          &lt;span style="color: #00f2fe;"&gt;${d.decade}&lt;/span&gt;
        &lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  `)}
&lt;/div&gt;`
